      SUBROUTINE IDIOTCC     PRINT INSTRUCTIONS WHICH AFFECT FITTINGCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'R.CIN'      INCLUDE 'YAW.CIN'CC     LOCAL VARIABLESCCC----------------------------------------------------------------C      IF (CDB .EQ. 7) GO TO 70      IF (CDB .EQ. 9) GO TO 90      IF (CDB .EQ. 11) GO TO 110      IF (CDB .EQ. 12) GO TO 120      IF (CDB .EQ. 13) GO TO 130      IF (CDB .EQ. 18) GO TO 180      IF (CDB .EQ. 20) GO TO 200      IF (CDB .EQ. 21) GO TO 210      IF (CDB .EQ. 22) GO TO 220      IF (CDB .GE. 40 .AND. CDB .LE. 43) GO TO 400      IF (CDB .EQ. 47) GO TO 470      IF (CDB .EQ. 48) GO TO 480      IF (CDB .EQ. 191) GO TO 1910      GO TO 2000C                     C     ACCELERATOR NOTATION FOR BEAM MATRIXC   70 ACCEL = .TRUE.      NORD1 = NORDX      NORD2 = 1      NORD3 = 1      GO TO 2000CC     SHIFT REMAINING BEAM LINE TO CENTER BEAMC   90 R1P = .FALSE.      IF (.NOT. (ALIGN .OR. LAY)) GO TO 2000      CALL OSET      IF (ALIGN) THEN        CALL ADVANC(2)        CALL ADVANC(3)      ENDIF      SOFA = .FALSE.      DO 91 J = 1, 6      CO(J) = CO(J) - COF(J)      IF (NORD1 .GT. 1 .AND. CO(J) .NE. 0.0) SOFA = .TRUE.   91 CONTINUE      RECENT = .FALSE.      GO TO 2000CC     LEVEL FLOOR COORDINATESC  110 IF (O(4,2,2) .NE. 0.0) ROLL = ATAN(O(4,1,2)/O(4,2,2))      IF (O(4,2,2) .EQ. 0.0 .AND. O(4,1,2) .GT. 0.0) ROLL = 0.5*PI      IF (O(4,2,2) .EQ. 0.0 .AND. O(4,1,2) .LT. 0.0) ROLL = - 0.5*PI      IF (O(4,2,2) .LT. 0.0) THEN        SHIFT = SIGN(PI,O(4,1,2))        ROLL = ROLL + SHIFT      ENDIF      IF (REFER) ROLL = ROLL + TOTROT      CSR = COS(ROLL)      SNR = SIN(ROLL)      R(4,4) = CSR      R(3,3) = CSR      R(2,2) = CSR      R(1,1) = CSR      R(2,4) = - SNR      R(1,3) = - SNR      R(4,2) = SNR      R(3,1) = SNR      GO TO 2000CC     FLOOR COORDINATESC  120 LAY = .TRUE.      GO TO 2000CC     REFER TRANSFER MATRIX TO ORIGINAL COORDINATE SYSTEMC  130 REFER = .TRUE.      GO TO 2000CC     SUPPRESS PRINTING OF CORRECTIONS AND COVARIANCE TABLEC  180 ONLY = .TRUE.      GO TO 2000CC     MISALIGNMENT PIVOTC  200 TMK = 1      MCFO = 100*TMK + MOD(MCFO,100)      GO TO 2000CC     EFFECT OF MISALIGNMENT OF FOCUSING ONLYC  210 MCFO = 1 + 10*(MCFO/10)      GO TO 2000CC     MISALIGNMENT ABOUT CHORD OF BEND MAGNETC  220 MCFO = 10 + 100*(MCFO/100) + MOD(MCFO,10)      GO TO 2000CC     POLE FACE ROTATION ANGLE SPECIFICATIONC  400 NPFR = CDB - 40      GO TO 2000CC     BENDING MAGNET DESCRIBED BY LENGTH AND FIELDC  470 ANIN = .FALSE.      GO TO 2000CC     BENDING MAGNET DESCRIBED BY LENGTH AND ANGLEC  480 ANIN = .TRUE.      GO TO 2000CC     FLOOR COORDINATES WITH EXTRA PRECISIONC 1910 LAY191 = .TRUE. 2000 RETURN      END